document.addEventListener("DOMContentLoaded",()=>{let t="simple";const e={btnSimple:document.getElementById("mode-simple"),btnCompound:document.getElementById("mode-compound"),rowCompound:document.getElementById("row-compound"),resultX:document.getElementById("result-x"),a1:document.getElementById("val-a1"),a2:document.getElementById("val-a2"),typeA:document.getElementById("type-a"),b1:document.getElementById("val-b1"),c1:document.getElementById("val-c1"),c2:document.getElementById("val-c2"),typeC:document.getElementById("type-c")};function n(){const n=parseFloat(e.a1.value),o=parseFloat(e.a2.value),i=parseFloat(e.b1.value);if(isNaN(n)||isNaN(o)||isNaN(i)||n===0){e.resultX.innerText="?";return}let s;if(t==="simple")e.typeA.value==="dir"?s=o*i/n:s=n*o/i;else{const t=parseFloat(e.c1.value),a=parseFloat(e.c2.value);if(isNaN(t)||isNaN(a)||t===0){e.resultX.innerText="?";return}let r=e.typeA.value==="dir"?o/n:n/o,c=e.typeC.value==="dir"?a/t:t/a;s=i*r*c}e.resultX.innerText=Number.isInteger(s)?s:s.toFixed(4).replace(/\.?0+$/,"")}e.btnSimple.addEventListener("click",()=>{t="simple",e.rowCompound.style.display="none",e.btnSimple.style.background="#3b82f6",e.btnSimple.style.color="white",e.btnCompound.style.background="transparent",e.btnCompound.style.color="#94a3b8",n()}),e.btnCompound.addEventListener("click",()=>{t="compound",e.rowCompound.style.display="grid",e.btnCompound.style.background="#3b82f6",e.btnCompound.style.color="white",e.btnSimple.style.background="transparent",e.btnSimple.style.color="#94a3b8",n()}),[e.a1,e.a2,e.b1,e.c1,e.c2,e.typeA,e.typeC].forEach(e=>{e.addEventListener("input",n)})})